1	//! A from-scratch Rust port of the `mapbox::earcut` polygon triangulator.
2	//!
3	//! Input is a polygon given as a list of rings: ring 0 is the outer contour and
4	//! every following ring is a hole. Vertex indices in the returned triangle list
5	//! refer to the flattened concatenation of all rings, so ring 1's first vertex
6	//! has index `ring0.len()`.
7	//!
8	//! The algorithm is ear clipping with three escalating fallbacks for input that
9	//! is not a simple polygon: filtering degenerate points, curing local
10	//! self-intersections, and finally splitting the ring along a valid diagonal.
11	//! Because that fallback ladder makes the output order depend on fine details
12	//! of the traversal, this port follows the reference control flow statement for
13	//! statement rather than reformulating it.
14	
15	pub mod geom;
16	pub mod node;
17	mod holes;
18	mod zorder;
19	
20	use self::geom::point_in_triangle;
21	pub use self::node::{Node, NIL};
22	
23	/// Triangulate a polygon, returning a flat list of triangle vertex indices.
24	///
25	/// Equivalent to `mapbox::earcut<uint32_t>(polygon)`.
26	pub fn earcut(polygon: &[Vec<[f64; 2]>]) -> Vec<u32> {
27	    let mut state = Earcut::new();
28	    state.run(polygon);
29	    state.indices
30	}
31	
32	/// Triangulation state: the node arena plus the z-order hash parameters.
33	pub struct Earcut {
34	    /// Flat triangle list, three vertex indices per triangle.
35	    pub indices: Vec<u32>,
36	    /// Number of vertices consumed by rings linked so far.
37	    vertices: usize,
38	    /// Arena backing every [`Node`]; handles into it are never invalidated.
39	    nodes: Vec<Node>,
40	
41	    hashing: bool,
42	    min_x: f64,
43	    max_x: f64,
44	    min_y: f64,
45	    max_y: f64,
46	    inv_size: f64,
47	}
48	
49	impl Default for Earcut {
50	    fn default() -> Self {
51	        Self::new()
52	    }
53	}
54	
55	impl Earcut {
56	    pub fn new() -> Self {
57	        Earcut {
58	            indices: Vec::new(),
59	            vertices: 0,
60	            nodes: Vec::new(),
61	            hashing: false,
62	            min_x: 0.0,
63	            max_x: 0.0,
64	            min_y: 0.0,
65	            max_y: 0.0,
66	            inv_size: 0.0,
67	        }
68	    }
69	
70	    /// `operator()(points)` — the top level driver.
71	    pub fn run(&mut self, points: &[Vec<[f64; 2]>]) {
72	        self.indices.clear();
73	        self.vertices = 0;
74	
75	        if points.is_empty() {
76	            return;
77	        }
78	
79	        // Decide whether the shape is complex enough to be worth hashing, and
80	        // size the arena while we are walking the rings. The loop stops early
81	        // once the threshold goes negative, so `len` is only a lower bound.
82	        let mut threshold: i32 = 80;
83	        let mut len: usize = 0;
84	        let mut i = 0;
85	        while threshold >= 0 && i < points.len() {
86	            threshold -= points[i].len() as i32;
87	            len += points[i].len();
88	            i += 1;
89	        }
90	
91	        self.nodes.reserve(len * 3 / 2);
92	        self.indices.reserve(len + points[0].len());
93	
94	        let mut outer_node = self.linked_list(&points[0], true);
95	        if outer_node == NIL || self.prev(outer_node) == self.next(outer_node) {
96	            return;
97	        }
98	
99	        if points.len() > 1 {
100	            outer_node = self.eliminate_holes(points, outer_node);
101	        }
102	
103	        // If the shape is not too simple we use a z-order curve hash later, so
104	        // calculate the polygon bbox now.
105	        self.hashing = threshold < 0;
106	        if self.hashing {
107	            let mut p = self.next(outer_node);
108	            self.min_x = self.x(outer_node);
109	            self.max_x = self.min_x;
110	            self.min_y = self.y(outer_node);
111	            self.max_y = self.min_y;
112	            loop {
113	                let (x, y) = (self.x(p), self.y(p));
114	                self.min_x = f64::min(self.min_x, x);
115	                self.min_y = f64::min(self.min_y, y);
116	                self.max_x = f64::max(self.max_x, x);
117	                self.max_y = f64::max(self.max_y, y);
118	                p = self.next(p);
119	                if p == outer_node {
120	                    break;
121	                }
122	            }
123	
124	            // min_x, min_y and inv_size transform coords into the integer range
125	            // the z-order calculation wants.
126	            self.inv_size = f64::max(self.max_x - self.min_x, self.max_y - self.min_y);
127	            self.inv_size = if self.inv_size != 0.0 {
128	                32767.0 / self.inv_size
129	            } else {
130	                0.0
131	            };
132	        }
133	
134	        self.earcut_linked(outer_node, 0);
135	
136	        self.nodes.clear();
137	    }
138	
139	    /// `earcutLinked(ear, pass)` — main ear slicing loop.
140	    fn earcut_linked(&mut self, ear: usize, pass: i32) {
141	        if ear == NIL {
142	            return;
143	        }
144	        let mut ear = ear;
145	
146	        // Interlink polygon nodes in z-order.
147	        if pass == 0 && self.hashing {
148	            self.index_curve(ear);
149	        }
150	
151	        let mut stop = ear;
152	
153	        // Iterate through ears, slicing them one by one.
154	        while self.prev(ear) != self.next(ear) {
155	            let prev = self.prev(ear);
156	            let next = self.next(ear);
157	
158	            let found = if self.hashing {
159	                self.is_ear_hashed(ear)
160	            } else {
161	                self.is_ear(ear)
162	            };
163	
164	            if found {
165	                // Cut off the triangle.
166	                self.indices.push(self.idx(prev));
167	                self.indices.push(self.idx(ear));
168	                self.indices.push(self.idx(next));
169	
170	                self.remove_node(ear);
171	
172	                // Skipping the next vertex leads to fewer sliver triangles.
173	                ear = self.next(next);
174	                stop = self.next(next);
175	
176	                continue;
177	            }
178	
179	            ear = next;
180	
181	            // If we looped through the whole remaining polygon and can't find
182	            // any more ears, escalate.
183	            if ear == stop {
184	                if pass == 0 {
185	                    // Try filtering points and slicing again.
186	                    let filtered = self.filter_points(ear, NIL);
187	                    self.earcut_linked(filtered, 1);
188	                } else if pass == 1 {
189	                    // If that didn't work, try curing all small
190	                    // self-intersections locally.
191	                    let filtered = self.filter_points(ear, NIL);
192	                    let cured = self.cure_local_intersections(filtered);
193	                    self.earcut_linked(cured, 2);
194	                } else if pass == 2 {
195	                    // As a last resort, try splitting the remaining polygon
196	                    // into two.
197	                    self.split_earcut(ear);
198	                }
199	
200	                break;
201	            }
202	        }
203	    }
204	
205	    /// `isEar(ear)` — linear scan ear test used when hashing is off.
206	    fn is_ear(&self, ear: usize) -> bool {
207	        let a = self.prev(ear);
208	        let b = ear;
209	        let c = self.next(ear);
210	
211	        if self.area(a, b, c) >= 0.0 {
212	            return false; // reflex, can't be an ear
213	        }
214	
215	        // Now make sure we don't have other points inside the potential ear.
216	        let mut p = self.next(self.next(ear));
217	
218	        while p != self.prev(ear) {
219	            if point_in_triangle(
220	                self.x(a),
221	                self.y(a),
222	                self.x(b),
223	                self.y(b),
224	                self.x(c),
225	                self.y(c),
226	                self.x(p),
227	                self.y(p),
228	            ) && self.area(self.prev(p), p, self.next(p)) >= 0.0
229	            {
230	                return false;
231	            }
232	            p = self.next(p);
233	        }
234	
235	        true
236	    }
237	
238	    /// `cureLocalIntersections(start)` — go through all polygon nodes and cure
239	    /// small local self-intersections.
240	    fn cure_local_intersections(&mut self, start: usize) -> usize {
241	        if start == NIL {
242	            return NIL;
243	        }
244	        let mut start = start;
245	        let mut p = start;
246	
247	        loop {
248	            let a = self.prev(p);
249	            let pn = self.next(p);
250	            let b = self.next(pn);
251	
252	            // A self-intersection where edge (v[i-1], v[i]) intersects
253	            // (v[i+1], v[i+2]).
254	            if !self.equals(a, b)
255	                && self.intersects(a, p, pn, b)
256	                && self.locally_inside(a, b)
257	                && self.locally_inside(b, a)
258	            {
259	                self.indices.push(self.idx(a));
260	                self.indices.push(self.idx(p));
261	                self.indices.push(self.idx(b));
262	
263	                // Remove the two nodes involved. `remove_node` leaves `p`'s own
264	                // links intact, so `p.next` still names the second victim.
265	                self.remove_node(p);
266	                let p_next = self.next(p);
267	                self.remove_node(p_next);
268	
269	                p = b;
270	                start = b;
271	            }
272	
273	            p = self.next(p);
274	            if p == start {
275	                break;
276	            }
277	        }
278	
279	        self.filter_points(p, NIL)
280	    }
281	
282	    /// `splitEarcut(start)` — try splitting the polygon into two, then
283	    /// triangulate both halves independently.
284	    fn split_earcut(&mut self, start: usize) {
285	        // Look for a valid diagonal that divides the polygon in two.
286	        let mut a = start;
287	        loop {
288	            let mut b = self.next(self.next(a));
289	            while b != self.prev(a) {
290	                if self.idx(a) != self.idx(b) && self.is_valid_diagonal(a, b) {
291	                    // Split the polygon in two by the diagonal.
292	                    let mut c = self.split_polygon(a, b);
293	
294	                    // Filter colinear points around the cuts.
295	                    let a_next = self.next(a);
296	                    let a = self.filter_points(a, a_next);
297	                    let c_next = self.next(c);
298	                    c = self.filter_points(c, c_next);
299	
300	                    // Run earcut on each half.
301	                    self.earcut_linked(a, 0);
302	                    self.earcut_linked(c, 0);
303	                    return;
304	                }
305	                b = self.next(b);
306	            }
307	            a = self.next(a);
308	            if a == start {
309	                break;
310	            }
311	        }
312	    }
313	}
