332	    fn square_with_a_real_hole() {
333	        let polygon = vec![
334	            vec![[0.0, 0.0], [4.0, 0.0], [4.0, 4.0], [0.0, 4.0]],
335	            vec![[1.0, 1.0], [1.0, 3.0], [3.0, 3.0], [3.0, 1.0]],
336	        ];
337	        let indices = earcut(&polygon);
338	        // Eight vertices, one hole: 2 * 8 - 2 - 2 * 1 = 8 triangles.
