1	//! The doubly linked ring node and the arena that owns it.
2	//!
3	//! The C++ implementation threads raw `Node*` pointers through every routine
4	//! and keeps them alive in an object pool that is only released at the very
5	//! end. Removed nodes therefore stay readable, and code such as
6	//! `removeNode(p); removeNode(p->next);` relies on that. We reproduce the
7	//! model exactly with a `Vec<Node>` arena and `usize` handles: a handle is
8	//! never invalidated, so identity comparisons (`p != ear.prev`) and reads of
9	//! unlinked nodes behave as they do in C++.
10	
11	use super::Earcut;
12	
13	/// Handle standing in for a null `Node*`.
14	pub const NIL: usize = usize::MAX;
15	
16	#[derive(Clone, Debug)]
17	pub struct Node {
18	    /// Index of this vertex in the flattened input coordinate list.
19	    pub i: u32,
20	    pub x: f64,
21	    pub y: f64,
22	
23	    /// Previous and next vertex nodes in the polygon ring.
24	    pub prev: usize,
25	    pub next: usize,
26	
27	    /// Z-order curve value.
28	    pub z: i32,
29	
30	    /// Previous and next nodes in z-order.
31	    pub prev_z: usize,
32	    pub next_z: usize,
33	
34	    /// Whether this is a Steiner point.
35	    pub steiner: bool,
36	}
37	
38	impl Node {
39	    pub fn new(i: u32, x: f64, y: f64) -> Self {
40	        Node {
41	            i,
42	            x,
43	            y,
44	            prev: NIL,
45	            next: NIL,
46	            z: 0,
47	            prev_z: NIL,
48	            next_z: NIL,
49	            steiner: false,
50	        }
51	    }
52	}
53	
54	impl Earcut {
55	    // -- field accessors -----------------------------------------------------
56	    //
57	    // Small copying getters keep every call site free of long-lived borrows,
58	    // which is what lets `&mut self` methods read and relink in one pass.
59	
60	    #[inline]
61	    pub(crate) fn x(&self, p: usize) -> f64 {
62	        self.nodes[p].x
63	    }
64	
65	    #[inline]
66	    pub(crate) fn y(&self, p: usize) -> f64 {
67	        self.nodes[p].y
68	    }
69	
70	    #[inline]
71	    pub(crate) fn idx(&self, p: usize) -> u32 {
72	        self.nodes[p].i
73	    }
74	
75	    #[inline]
76	    pub(crate) fn next(&self, p: usize) -> usize {
77	        self.nodes[p].next
78	    }
79	
80	    #[inline]
81	    pub(crate) fn prev(&self, p: usize) -> usize {
82	        self.nodes[p].prev
83	    }
84	
85	    // -- arena ---------------------------------------------------------------
86	
87	    /// `nodes.construct(i, x, y)`
88	    pub(crate) fn construct(&mut self, i: u32, x: f64, y: f64) -> usize {
89	        self.nodes.push(Node::new(i, x, y));
90	        self.nodes.len() - 1
91	    }
92	
93	    /// `insertNode(i, point, last)` — create a node and splice it after `last`.
94	    pub(crate) fn insert_node(&mut self, i: usize, pt: [f64; 2], last: usize) -> usize {
95	        let p = self.construct(i as u32, pt[0], pt[1]);
96	
97	        if last == NIL {
98	            self.nodes[p].prev = p;
99	            self.nodes[p].next = p;
100	        } else {
101	            let last_next = self.nodes[last].next;
102	            self.nodes[p].next = last_next;
103	            self.nodes[p].prev = last;
104	            self.nodes[last_next].prev = p;
105	            self.nodes[last].next = p;
106	        }
107	
108	        p
109	    }
110	
111	    /// `removeNode(p)` — unlink from both the ring and the z-order list.
112	    ///
113	    /// As in C++, `p`'s own `next`/`prev` fields are deliberately left intact.
114	    pub(crate) fn remove_node(&mut self, p: usize) {
115	        let (pn, pp) = (self.nodes[p].next, self.nodes[p].prev);
116	        self.nodes[pn].prev = pp;
117	        self.nodes[pp].next = pn;
118	
119	        let (pz, nz) = (self.nodes[p].prev_z, self.nodes[p].next_z);
120	        if pz != NIL {
121	            self.nodes[pz].next_z = nz;
122	        }
123	        if nz != NIL {
124	            self.nodes[nz].prev_z = pz;
125	        }
126	    }
127	
128	    /// `splitPolygon(a, b)` — link two ring vertices with a bridge, splitting
129	    /// the ring into two. Returns the second ring's entry node (`b2`).
130	    pub(crate) fn split_polygon(&mut self, a: usize, b: usize) -> usize {
131	        let a2 = self.construct(self.nodes[a].i, self.nodes[a].x, self.nodes[a].y);
132	        let b2 = self.construct(self.nodes[b].i, self.nodes[b].x, self.nodes[b].y);
133	        let an = self.nodes[a].next;
134	        let bp = self.nodes[b].prev;
135	
136	        self.nodes[a].next = b;
137	        self.nodes[b].prev = a;
138	
139	        self.nodes[a2].next = an;
140	        self.nodes[an].prev = a2;
141	
142	        self.nodes[b2].next = a2;
143	        self.nodes[a2].prev = b2;
144	
145	        self.nodes[bp].next = b2;
146	        self.nodes[b2].prev = bp;
147	
148	        b2
149	    }
150	
151	    /// `filterPoints(start, end)` — drop colinear or duplicate points.
152	    ///
153	    /// Pass [`NIL`] for `end` to get the C++ default argument (`end = start`).
154	    pub(crate) fn filter_points(&mut self, start: usize, end: usize) -> usize {
155	        if start == NIL {
156	            return NIL;
157	        }
158	        let mut end = if end == NIL { start } else { end };
159	
160	        let mut p = start;
161	        loop {
162	            let mut again = false;
163	
164	            let pn = self.nodes[p].next;
165	            let pp = self.nodes[p].prev;
166	            if !self.nodes[p].steiner && (self.equals(p, pn) || self.area(pp, p, pn) == 0.0) {
167	                self.remove_node(p);
168	                p = pp;
169	                end = pp;
170	
171	                if p == self.nodes[p].next {
172	                    break;
173	                }
174	                again = true;
175	            } else {
176	                p = pn;
177	            }
178	
179	            if !(again || p != end) {
180	                break;
181	            }
182	        }
183	
184	        end
185	    }
186	
187	    /// `linkedList(points, clockwise)` — build a circular doubly linked list
188	    /// from one ring, in the requested winding order.
189	    pub(crate) fn linked_list(&mut self, points: &[[f64; 2]], clockwise: bool) -> usize {
190	        let len = points.len();
191	        let mut last = NIL;
192	
193	        // Calculate the original winding order of the ring.
194	        let mut sum = 0.0f64;
195	        if len > 0 {
196	            let mut j = len - 1;
197	            for i in 0..len {
198	                let p1 = points[i];
199	                let p2 = points[j];
200	                sum += (p2[0] - p1[0]) * (p1[1] + p2[1]);
201	                j = i;
202	            }
203	        }
204	
205	        // Link points in the specified winding order.
206	        if clockwise == (sum > 0.0) {
207	            for i in 0..len {
208	                last = self.insert_node(self.vertices + i, points[i], last);
209	            }
210	        } else {
211	            for i in (0..len).rev() {
212	                last = self.insert_node(self.vertices + i, points[i], last);
213	            }
214	        }
215	
216	        if last != NIL {
217	            let last_next = self.nodes[last].next;
218	            if self.equals(last, last_next) {
219	                self.remove_node(last);
220	                last = last_next;
221	            }
222	        }
223	
224	        self.vertices += len;
225	
226	        last
227	    }
228	}
