1	//! Geometric predicates.
2	//!
3	//! Every expression here is kept in the exact algebraic form the C++ uses.
4	//! Rearranging them (even into a mathematically equivalent shape) changes
5	//! floating point rounding and can flip a `>= 0` test on a degenerate input,
6	//! which in turn changes which ear is clipped and therefore the output order.
7	
8	use super::Earcut;
9	
10	/// `area(p, q, r)` — twice the signed area of the triangle, negative for a
11	/// counter-clockwise turn.
12	#[inline]
13	pub fn area_xy(px: f64, py: f64, qx: f64, qy: f64, rx: f64, ry: f64) -> f64 {
14	    (qy - py) * (rx - qx) - (qx - px) * (ry - qy)
15	}
16	
17	/// `pointInTriangle(...)` — boundary counts as inside (all tests are `>= 0`).
18	#[inline]
19	#[allow(clippy::too_many_arguments)]
20	pub fn point_in_triangle(
21	    ax: f64,
22	    ay: f64,
23	    bx: f64,
24	    by: f64,
25	    cx: f64,
26	    cy: f64,
27	    px: f64,
28	    py: f64,
29	) -> bool {
30	    (cx - px) * (ay - py) - (ax - px) * (cy - py) >= 0.0
31	        && (ax - px) * (by - py) - (bx - px) * (ay - py) >= 0.0
32	        && (bx - px) * (cy - py) - (cx - px) * (by - py) >= 0.0
33	}
34	
35	/// `sign(val)` — `(0 < val) - (val < 0)`.
36	#[inline]
37	pub fn sign(val: f64) -> i32 {
38	    i32::from(0.0 < val) - i32::from(val < 0.0)
39	}
40	
41	impl Earcut {
42	    #[inline]
43	    pub(crate) fn area(&self, p: usize, q: usize, r: usize) -> f64 {
44	        area_xy(
45	            self.x(p),
46	            self.y(p),
47	            self.x(q),
48	            self.y(q),
49	            self.x(r),
50	            self.y(r),
51	        )
52	    }
53	
54	    /// `equals(p1, p2)` — exact coordinate equality.
55	    #[inline]
56	    pub(crate) fn equals(&self, p1: usize, p2: usize) -> bool {
57	        self.x(p1) == self.x(p2) && self.y(p1) == self.y(p2)
58	    }
59	
60	    /// `onSegment(p, q, r)` — `q` lies inside the bounding box of `pr`.
61	    #[inline]
62	    pub(crate) fn on_segment(&self, p: usize, q: usize, r: usize) -> bool {
63	        self.x(q) <= f64::max(self.x(p), self.x(r))
64	            && self.x(q) >= f64::min(self.x(p), self.x(r))
65	            && self.y(q) <= f64::max(self.y(p), self.y(r))
66	            && self.y(q) >= f64::min(self.y(p), self.y(r))
67	    }
68	
69	    /// `intersects(p1, q1, p2, q2)` — do the two segments properly or
70	    /// colinearly intersect?
71	    pub(crate) fn intersects(&self, p1: usize, q1: usize, p2: usize, q2: usize) -> bool {
72	        let o1 = sign(self.area(p1, q1, p2));
73	        let o2 = sign(self.area(p1, q1, q2));
74	        let o3 = sign(self.area(p2, q2, p1));
75	        let o4 = sign(self.area(p2, q2, q1));
76	
77	        if o1 != o2 && o3 != o4 {
78	            return true; // general case
79	        }
80	
81	        if o1 == 0 && self.on_segment(p1, p2, q1) {
82	            return true; // p1, q1 and p2 are colinear and p2 lies on p1q1
83	        }
84	        if o2 == 0 && self.on_segment(p1, q2, q1) {
85	            return true; // p1, q1 and q2 are colinear and q2 lies on p1q1
86	        }
87	        if o3 == 0 && self.on_segment(p2, p1, q2) {
88	            return true; // p2, q2 and p1 are colinear and p1 lies on p2q2
89	        }
90	        if o4 == 0 && self.on_segment(p2, q1, q2) {
91	            return true; // p2, q2 and q1 are colinear and q1 lies on p2q2
92	        }
93	
94	        false
95	    }
96	
97	    /// `intersectsPolygon(a, b)` — does the diagonal `ab` cross any ring edge?
98	    pub(crate) fn intersects_polygon(&self, a: usize, b: usize) -> bool {
99	        let mut p = a;
100	        loop {
101	            let pn = self.next(p);
102	            if self.idx(p) != self.idx(a)
103	                && self.idx(pn) != self.idx(a)
104	                && self.idx(p) != self.idx(b)
105	                && self.idx(pn) != self.idx(b)
106	                && self.intersects(p, pn, a, b)
107	            {
108	                return true;
109	            }
110	            p = pn;
111	            if p == a {
112	                break;
113	            }
114	        }
115	
116	        false
117	    }
118	
119	    /// `locallyInside(a, b)` — is the segment `ab` inside the polygon in the
120	    /// immediate neighbourhood of `a`?
121	    pub(crate) fn locally_inside(&self, a: usize, b: usize) -> bool {
122	        let ap = self.prev(a);
123	        let an = self.next(a);
124	        if self.area(ap, a, an) < 0.0 {
125	            self.area(a, b, an) >= 0.0 && self.area(a, ap, b) >= 0.0
126	        } else {
127	            self.area(a, b, ap) < 0.0 || self.area(a, an, b) < 0.0
128	        }
129	    }
130	
131	    /// `middleInside(a, b)` — is the midpoint of `ab` inside the polygon?
132	    pub(crate) fn middle_inside(&self, a: usize, b: usize) -> bool {
133	        let mut p = a;
134	        let mut inside = false;
135	        let px = (self.x(a) + self.x(b)) / 2.0;
136	        let py = (self.y(a) + self.y(b)) / 2.0;
137	        loop {
138	            let pn = self.next(p);
139	            if ((self.y(p) > py) != (self.y(pn) > py))
140	                && self.y(pn) != self.y(p)
141	                && (px
142	                    < (self.x(pn) - self.x(p)) * (py - self.y(p)) / (self.y(pn) - self.y(p))
143	                        + self.x(p))
144	            {
145	                inside = !inside;
146	            }
147	            p = pn;
148	            if p == a {
149	                break;
150	            }
151	        }
152	
153	        inside
154	    }
155	
156	    /// `isValidDiagonal(a, b)` — can the polygon be split along `ab`?
157	    pub(crate) fn is_valid_diagonal(&self, a: usize, b: usize) -> bool {
158	        let an = self.next(a);
159	        let ap = self.prev(a);
160	        let bp = self.prev(b);
161	        let bn = self.next(b);
162	
163	        self.idx(an) != self.idx(b)
164	            && self.idx(ap) != self.idx(b)
165	            && !self.intersects_polygon(a, b) // doesn't intersect other edges
166	            && ((self.locally_inside(a, b)
167	                && self.locally_inside(b, a)
168	                && self.middle_inside(a, b)   // locally visible
169	                // does not create opposite-facing sectors
170	                && (self.area(ap, a, bp) != 0.0 || self.area(a, bp, b) != 0.0))
171	                // special zero-length case
172	                || (self.equals(a, b)
173	                    && self.area(ap, a, an) > 0.0
174	                    && self.area(bp, b, bn) > 0.0))
175	    }
176	
177	    /// `sectorContainsSector(m, p)` — whether the sector at `m` contains the
178	    /// sector at `p`.
179	    pub(crate) fn sector_contains_sector(&self, m: usize, p: usize) -> bool {
180	        self.area(self.prev(m), m, self.prev(p)) < 0.0
181	            && self.area(self.next(p), m, self.next(m)) < 0.0
182	    }
183	}
