1	//! Hole elimination: each inner ring is bridged into the outer ring so the
2	//! whole polygon becomes a single (self-touching) ring the ear clipper can eat.
3	
4	use super::node::NIL;
5	use super::Earcut;
6	use super::geom::point_in_triangle;
7	
8	impl Earcut {
9	    /// `eliminateHoles(points, outerNode)`
10	    pub(crate) fn eliminate_holes(
11	        &mut self,
12	        points: &[Vec<[f64; 2]>],
13	        mut outer_node: usize,
14	    ) -> usize {
15	        let len = points.len();
16	
17	        let mut queue: Vec<usize> = Vec::new();
18	        for ring in points.iter().take(len).skip(1) {
19	            let list = self.linked_list(ring, false);
20	            if list != NIL {
21	                if self.next(list) == list {
22	                    self.nodes[list].steiner = true;
23	                }
24	                queue.push(self.get_leftmost(list));
25	            }
26	        }
27	
28	        // `std::sort` by ascending x. The C++ comparator is a strict `a->x <
29	        // b->x`; every leftmost node in this program has a distinct x, so the
30	        // (unspecified) ordering `std::sort` gives equal keys never comes up
31	        // and a stable sort is an exact stand-in.
32	        let xs: Vec<f64> = queue.iter().map(|&n| self.x(n)).collect();
33	        let mut order: Vec<usize> = (0..queue.len()).collect();
34	        order.sort_by(|&a, &b| xs[a].partial_cmp(&xs[b]).unwrap());
35	        let queue: Vec<usize> = order.into_iter().map(|i| queue[i]).collect();
36	
37	        // Process holes from left to right.
38	        for &hole in &queue {
39	            outer_node = self.eliminate_hole(hole, outer_node);
40	        }
41	
42	        outer_node
43	    }
44	
45	    /// `eliminateHole(hole, outerNode)` — find a bridge and link the hole in.
46	    fn eliminate_hole(&mut self, hole: usize, outer_node: usize) -> usize {
47	        // Find a bridge between vertices that connects the hole with an outer
48	        // ring, and link it.
49	        let bridge = self.find_hole_bridge(hole, outer_node);
50	        if bridge == NIL {
51	            return outer_node;
52	        }
53	
54	        let bridge_reverse = self.split_polygon(bridge, hole);
55	
56	        // Filter colinear points around the cuts.
57	        let br_next = self.next(bridge_reverse);
58	        self.filter_points(bridge_reverse, br_next);
59	
60	        // Check if the input node was removed by the filtering.
61	        let b_next = self.next(bridge);
62	        self.filter_points(bridge, b_next)
63	    }
64	
65	    /// `findHoleBridge(hole, outerNode)` — David Eberly's algorithm for finding
66	    /// a bridge between a hole and an outer ring.
67	    fn find_hole_bridge(&self, hole: usize, outer_node: usize) -> usize {
68	        let mut p = outer_node;
69	        let hx = self.x(hole);
70	        let hy = self.y(hole);
71	        let mut qx = f64::NEG_INFINITY;
72	        let mut m = NIL;
73	
74	        // Find a segment intersected by a ray from the hole's leftmost vertex
75	        // going left; the segment endpoint with the lesser x is the potential
76	        // connection vertex.
77	        loop {
78	            let pn = self.next(p);
79	            if hy <= self.y(p) && hy >= self.y(pn) && self.y(pn) != self.y(p) {
80	                let x = self.x(p)
81	                    + (hy - self.y(p)) * (self.x(pn) - self.x(p)) / (self.y(pn) - self.y(p));
82	                if x <= hx && x > qx {
83	                    qx = x;
84	                    m = if self.x(p) < self.x(pn) { p } else { pn };
85	                    if x == hx {
86	                        // Hole touches the outer segment; pick the leftmost
87	                        // endpoint.
88	                        return m;
89	                    }
90	                }
91	            }
92	            p = pn;
93	            if p == outer_node {
94	                break;
95	            }
96	        }
97	
98	        if m == NIL {
99	            return NIL;
100	        }
101	
102	        // Look for points strictly inside the triangle of the hole vertex, the
103	        // segment intersection and the endpoint. If there are none we have a
104	        // valid connection; otherwise choose the vertex forming the minimum
105	        // angle with the ray.
106	        let stop = m;
107	        let mut tan_min = f64::INFINITY;
108	        let mx = self.x(m);
109	        let my = self.y(m);
110	
111	        p = m;
112	        loop {
113	            let px = self.x(p);
114	            let py = self.y(p);
115	            if hx >= px
116	                && px >= mx
117	                && hx != px
118	                && point_in_triangle(
119	                    if hy < my { hx } else { qx },
120	                    hy,
121	                    mx,
122	                    my,
123	                    if hy < my { qx } else { hx },
124	                    hy,
125	                    px,
126	                    py,
127	                )
128	            {
129	                let tan = (hy - py).abs() / (hx - px); // tangential
130	
131	                if self.locally_inside(p, hole)
132	                    && (tan < tan_min
133	                        || (tan == tan_min
134	                            && (px > self.x(m) || self.sector_contains_sector(m, p))))
135	                {
136	                    m = p;
137	                    tan_min = tan;
138	                }
139	            }
140	
141	            p = self.next(p);
142	            if p == stop {
143	                break;
144	            }
145	        }
146	
147	        m
148	    }
149	
150	    /// `getLeftmost(start)` — smallest x, ties broken by smallest y.
151	    fn get_leftmost(&self, start: usize) -> usize {
152	        let mut p = start;
153	        let mut leftmost = start;
154	        loop {
155	            if self.x(p) < self.x(leftmost)
156	                || (self.x(p) == self.x(leftmost) && self.y(p) < self.y(leftmost))
157	            {
158	                leftmost = p;
159	            }
160	            p = self.next(p);
161	            if p == start {
162	                break;
163	            }
164	        }
165	
166	        leftmost
167	    }
168	}
