1	//! Z-order (Morton code) spatial hash.
2	//!
3	//! For polygons above a size threshold the ear test consults a z-order sorted
4	//! list instead of walking every remaining vertex. It is purely an
5	//! acceleration structure: the set of candidate points it visits is the same
6	//! set the linear scan would find inside the triangle, so both paths must
7	//! produce the same triangulation.
8	
9	use super::geom::point_in_triangle;
10	use super::node::NIL;
11	use super::Earcut;
12	
13	impl Earcut {
14	    /// `zOrder(x, y)` — interleave the bits of the two 15-bit coordinates.
15	    pub(crate) fn z_order(&self, x_: f64, y_: f64) -> i32 {
16	        // Coords are transformed into a non-negative 15-bit integer range.
17	        // The C++ `static_cast<int32_t>` truncates toward zero, which is what
18	        // Rust's `as` does for in-range values.
19	        let mut x = ((x_ - self.min_x) * self.inv_size) as i32;
20	        let mut y = ((y_ - self.min_y) * self.inv_size) as i32;
21	
22	        x = (x | (x << 8)) & 0x00FF_00FF;
23	        x = (x | (x << 4)) & 0x0F0F_0F0F;
24	        x = (x | (x << 2)) & 0x3333_3333;
25	        x = (x | (x << 1)) & 0x5555_5555;
26	
27	        y = (y | (y << 8)) & 0x00FF_00FF;
28	        y = (y | (y << 4)) & 0x0F0F_0F0F;
29	        y = (y | (y << 2)) & 0x3333_3333;
30	        y = (y | (y << 1)) & 0x5555_5555;
31	
32	        x | (y << 1)
33	    }
34	
35	    /// `indexCurve(start)` — attach a z-order sorted linked list to the ring.
36	    pub(crate) fn index_curve(&mut self, start: usize) {
37	        debug_assert!(start != NIL);
38	        let mut p = start;
39	
40	        loop {
41	            if self.nodes[p].z == 0 {
42	                self.nodes[p].z = self.z_order(self.x(p), self.y(p));
43	            }
44	            self.nodes[p].prev_z = self.nodes[p].prev;
45	            self.nodes[p].next_z = self.nodes[p].next;
46	            p = self.nodes[p].next;
47	            if p == start {
48	                break;
49	            }
50	        }
51	
52	        // Break the circle so the merge sort sees a plain list.
53	        let pz = self.nodes[p].prev_z;
54	        self.nodes[pz].next_z = NIL;
55	        self.nodes[p].prev_z = NIL;
56	
57	        self.sort_linked(p);
58	    }
59	
60	    /// `sortLinked(list)` — bottom-up merge sort of the z-order linked list.
61	    ///
62	    /// The `p.z <= q.z` comparison makes the sort stable, so nodes with equal
63	    /// z keep their ring order. That ordering is observable in the output.
64	    pub(crate) fn sort_linked(&mut self, list: usize) -> usize {
65	        debug_assert!(list != NIL);
66	        let mut list = list;
67	        let mut in_size: i32 = 1;
68	
69	        loop {
70	            let mut p = list;
71	            list = NIL;
72	            let mut tail = NIL;
73	            let mut num_merges = 0;
74	
75	            while p != NIL {
76	                num_merges += 1;
77	                let mut q = p;
78	                let mut p_size: i32 = 0;
79	                for _ in 0..in_size {
80	                    p_size += 1;
81	                    q = self.nodes[q].next_z;
82	                    if q == NIL {
83	                        break;
84	                    }
85	                }
86	
87	                let mut q_size = in_size;
88	
89	                while p_size > 0 || (q_size > 0 && q != NIL) {
90	                    let e;
91	                    if p_size == 0 {
92	                        e = q;
93	                        q = self.nodes[q].next_z;
94	                        q_size -= 1;
95	                    } else if q_size == 0 || q == NIL {
96	                        e = p;
97	                        p = self.nodes[p].next_z;
98	                        p_size -= 1;
99	                    } else if self.nodes[p].z <= self.nodes[q].z {
100	                        e = p;
101	                        p = self.nodes[p].next_z;
102	                        p_size -= 1;
103	                    } else {
104	                        e = q;
105	                        q = self.nodes[q].next_z;
106	                        q_size -= 1;
107	                    }
108	
109	                    if tail != NIL {
110	                        self.nodes[tail].next_z = e;
111	                    } else {
112	                        list = e;
113	                    }
114	
115	                    self.nodes[e].prev_z = tail;
116	                    tail = e;
117	                }
118	
119	                p = q;
120	            }
121	
122	            self.nodes[tail].next_z = NIL;
123	
124	            if num_merges <= 1 {
125	                return list;
126	            }
127	
128	            in_size *= 2;
129	        }
130	    }
131	
132	    /// `isEarHashed(ear)` — the z-order accelerated ear test.
133	    pub(crate) fn is_ear_hashed(&self, ear: usize) -> bool {
134	        let a = self.prev(ear);
135	        let b = ear;
136	        let c = self.next(ear);
137	
138	        if self.area(a, b, c) >= 0.0 {
139	            return false; // reflex, can't be an ear
140	        }
141	
142	        let (ax, ay) = (self.x(a), self.y(a));
143	        let (bx, by) = (self.x(b), self.y(b));
144	        let (cx, cy) = (self.x(c), self.y(c));
145	
146	        // Triangle bbox; min & max are calculated like this for speed.
147	        let min_tx = f64::min(ax, f64::min(bx, cx));
148	        let min_ty = f64::min(ay, f64::min(by, cy));
149	        let max_tx = f64::max(ax, f64::max(bx, cx));
150	        let max_ty = f64::max(ay, f64::max(by, cy));
151	
152	        // Z-order range for the current triangle bbox.
153	        let min_z = self.z_order(min_tx, min_ty);
154	        let max_z = self.z_order(max_tx, max_ty);
155	
156	        let mut p = self.nodes[ear].prev_z;
157	        let mut n = self.nodes[ear].next_z;
158	
159	        // Look for points inside the triangle in both directions.
160	        while p != NIL && self.nodes[p].z >= min_z && n != NIL && self.nodes[n].z <= max_z {
161	            if self.x(p) >= min_tx
162	                && self.x(p) <= max_tx
163	                && self.y(p) >= min_ty
164	                && self.y(p) <= max_ty
165	                && p != a
166	                && p != c
167	                && point_in_triangle(ax, ay, bx, by, cx, cy, self.x(p), self.y(p))
168	                && self.area(self.prev(p), p, self.next(p)) >= 0.0
169	            {
170	                return false;
171	            }
172	            p = self.nodes[p].prev_z;
173	
174	            if self.x(n) >= min_tx
175	                && self.x(n) <= max_tx
176	                && self.y(n) >= min_ty
177	                && self.y(n) <= max_ty
178	                && n != a
179	                && n != c
180	                && point_in_triangle(ax, ay, bx, by, cx, cy, self.x(n), self.y(n))
181	                && self.area(self.prev(n), n, self.next(n)) >= 0.0
182	            {
183	                return false;
184	            }
185	            n = self.nodes[n].next_z;
186	        }
187	
188	        // Look for remaining points in decreasing z-order.
189	        while p != NIL && self.nodes[p].z >= min_z {
190	            if p != a
191	                && p != c
192	                && point_in_triangle(ax, ay, bx, by, cx, cy, self.x(p), self.y(p))
193	                && self.area(self.prev(p), p, self.next(p)) >= 0.0
194	            {
195	                return false;
196	            }
197	            p = self.nodes[p].prev_z;
198	        }
199	
200	        // Look for remaining points in increasing z-order.
201	        while n != NIL && self.nodes[n].z <= max_z {
202	            if n != a
203	                && n != c
204	                && point_in_triangle(ax, ay, bx, by, cx, cy, self.x(n), self.y(n))
205	                && self.area(self.prev(n), n, self.next(n)) >= 0.0
206	            {
207	                return false;
208	            }
209	            n = self.nodes[n].next_z;
210	        }
211	
212	        true
213	    }
214	}
