1	//! The polygon `test4.cpp` builds.
2	//!
3	//! `n` rings, each an axis-aligned square of side `n` whose lower-left corner
4	//! sits at `(2i, 2i)`. Because the offset step (2) is smaller than the side
5	//! (`n`) for all `n > 2`, the rings overlap heavily instead of nesting, so
6	//! earcut sees a badly self-intersecting polygon and exercises its fallback
7	//! paths. Ring 0 is treated as the outer contour and rings 1.. as holes.
8	
9	/// Build the polygon for a given `n`. A non-positive `n` yields no rings,
10	/// exactly as the C++ `for (int i = 0; i < n; i++)` loop does.
11	pub fn overlapping_squares(n: i32) -> Vec<Vec<[f64; 2]>> {
12	    let mut polygon: Vec<Vec<[f64; 2]>> = Vec::new();
13	
14	    let side = f64::from(n);
15	    let mut i: i32 = 0;
16	    while i < n {
17	        // `double offset = i * 2;` — int multiply, then widen.
18	        let offset = f64::from(i.wrapping_mul(2));
19	        polygon.push(vec![
20	            [offset, offset],
21	            [offset + side, offset],
22	            [offset + side, offset + side],
23	            [offset, offset + side],
24	        ]);
25	        i += 1;
26	    }
27	
28	    polygon
29	}
30	
31	#[cfg(test)]
32	mod tests {
33	    use super::overlapping_squares;
34	
35	    #[test]
36	    fn shape_matches_the_cpp_loop() {
37	        assert!(overlapping_squares(0).is_empty());
38	        assert!(overlapping_squares(-3).is_empty());
39	
40	        let p = overlapping_squares(3);
41	        assert_eq!(p.len(), 3);
42	        assert!(p.iter().all(|ring| ring.len() == 4));
43	        assert_eq!(p[0], [[0.0, 0.0], [3.0, 0.0], [3.0, 3.0], [0.0, 3.0]]);
44	        assert_eq!(p[2], [[4.0, 4.0], [7.0, 4.0], [7.0, 7.0], [4.0, 7.0]]);
45	    }
46	}
