// Independent earcut reference, transliterated from my own from-memory model
// of mapbox/earcut.hpp (see /tmp/ref/earcut_ref.py).
#![allow(dead_code, clippy::all)]

pub const NIL: usize = usize::MAX;

#[derive(Clone)]
pub struct Nd {
    pub i: u32,
    pub x: f64,
    pub y: f64,
    pub prev: usize,
    pub next: usize,
    pub z: i32,
    pub pz: usize,
    pub nz: usize,
    pub steiner: bool,
}

pub struct R {
    pub ind: Vec<u32>,
    pub verts: usize,
    pub nd: Vec<Nd>,
    pub hashing: bool,
    pub min_x: f64,
    pub max_x: f64,
    pub min_y: f64,
    pub max_y: f64,
    pub inv: f64,
}

fn area_(px: f64, py: f64, qx: f64, qy: f64, rx: f64, ry: f64) -> f64 {
    (qy - py) * (rx - qx) - (qx - px) * (ry - qy)
}
fn sgn(v: f64) -> i32 {
    (0.0 < v) as i32 - (v < 0.0) as i32
}
fn pit(ax: f64, ay: f64, bx: f64, by: f64, cx: f64, cy: f64, px: f64, py: f64) -> bool {
    (cx - px) * (ay - py) - (ax - px) * (cy - py) >= 0.0
        && (ax - px) * (by - py) - (bx - px) * (ay - py) >= 0.0
        && (bx - px) * (cy - py) - (cx - px) * (by - py) >= 0.0
}

impl R {
    pub fn new() -> R {
        R { ind: vec![], verts: 0, nd: vec![], hashing: false, min_x: 0.0, max_x: 0.0, min_y: 0.0, max_y: 0.0, inv: 0.0 }
    }
    fn x(&self, p: usize) -> f64 { self.nd[p].x }
    fn y(&self, p: usize) -> f64 { self.nd[p].y }
    fn nx(&self, p: usize) -> usize { self.nd[p].next }
    fn pv(&self, p: usize) -> usize { self.nd[p].prev }
    fn area(&self, p: usize, q: usize, r: usize) -> f64 {
        area_(self.x(p), self.y(p), self.x(q), self.y(q), self.x(r), self.y(r))
    }
    fn eq(&self, a: usize, b: usize) -> bool { self.x(a) == self.x(b) && self.y(a) == self.y(b) }
    fn on_seg(&self, p: usize, q: usize, r: usize) -> bool {
        self.x(q) <= self.x(p).max(self.x(r)) && self.x(q) >= self.x(p).min(self.x(r))
            && self.y(q) <= self.y(p).max(self.y(r)) && self.y(q) >= self.y(p).min(self.y(r))
    }
    fn inter(&self, p1: usize, q1: usize, p2: usize, q2: usize) -> bool {
        let o1 = sgn(self.area(p1, q1, p2));
        let o2 = sgn(self.area(p1, q1, q2));
        let o3 = sgn(self.area(p2, q2, p1));
        let o4 = sgn(self.area(p2, q2, q1));
        if o1 != o2 && o3 != o4 { return true; }
        if o1 == 0 && self.on_seg(p1, p2, q1) { return true; }
        if o2 == 0 && self.on_seg(p1, q2, q1) { return true; }
        if o3 == 0 && self.on_seg(p2, p1, q2) { return true; }
        if o4 == 0 && self.on_seg(p2, q1, q2) { return true; }
        false
    }
    fn loc_in(&self, a: usize, b: usize) -> bool {
        if self.area(self.pv(a), a, self.nx(a)) < 0.0 {
            self.area(a, b, self.nx(a)) >= 0.0 && self.area(a, self.pv(a), b) >= 0.0
        } else {
            self.area(a, b, self.pv(a)) < 0.0 || self.area(a, self.nx(a), b) < 0.0
        }
    }
    fn mid_in(&self, a: usize, b: usize) -> bool {
        let mut p = a;
        let mut inside = false;
        let px = (self.x(a) + self.x(b)) / 2.0;
        let py = (self.y(a) + self.y(b)) / 2.0;
        loop {
            let n = self.nx(p);
            if ((self.y(p) > py) != (self.y(n) > py)) && self.y(n) != self.y(p)
                && (px < (self.x(n) - self.x(p)) * (py - self.y(p)) / (self.y(n) - self.y(p)) + self.x(p))
            { inside = !inside; }
            p = n;
            if p == a { break; }
        }
        inside
    }
    fn sect(&self, m: usize, p: usize) -> bool {
        self.area(self.pv(m), m, self.pv(p)) < 0.0 && self.area(self.nx(p), m, self.nx(m)) < 0.0
    }
    fn rm(&mut self, p: usize) {
        let (n, pr) = (self.nd[p].next, self.nd[p].prev);
        self.nd[n].prev = pr;
        self.nd[pr].next = n;
        let (pz, nz) = (self.nd[p].pz, self.nd[p].nz);
        if pz != NIL { self.nd[pz].nz = nz; }
        if nz != NIL { self.nd[nz].pz = pz; }
    }
    fn mk(&mut self, i: u32, x: f64, y: f64) -> usize {
        self.nd.push(Nd { i, x, y, prev: NIL, next: NIL, z: 0, pz: NIL, nz: NIL, steiner: false });
        self.nd.len() - 1
    }
    fn ins(&mut self, i: usize, pt: [f64; 2], last: usize) -> usize {
        let p = self.mk(i as u32, pt[0], pt[1]);
        if last == NIL {
            self.nd[p].prev = p;
            self.nd[p].next = p;
        } else {
            let ln = self.nd[last].next;
            self.nd[p].next = ln;
            self.nd[p].prev = last;
            self.nd[ln].prev = p;
            self.nd[last].next = p;
        }
        p
    }
    fn filt(&mut self, start: usize, end0: usize) -> usize {
        if start == NIL { return NIL; }
        let mut end = if end0 == NIL { start } else { end0 };
        let mut p = start;
        loop {
            let mut again = false;
            let cond = !self.nd[p].steiner
                && (self.eq(p, self.nx(p)) || self.area(self.pv(p), p, self.nx(p)) == 0.0);
            if cond {
                self.rm(p);
                p = self.nd[p].prev;
                end = p;
                if p == self.nd[p].next { break; }
                again = true;
            } else {
                p = self.nd[p].next;
            }
            if !(again || p != end) { break; }
        }
        end
    }
    fn split_poly(&mut self, a: usize, b: usize) -> usize {
        let a2 = self.mk(self.nd[a].i, self.nd[a].x, self.nd[a].y);
        let b2 = self.mk(self.nd[b].i, self.nd[b].x, self.nd[b].y);
        let an = self.nd[a].next;
        let bp = self.nd[b].prev;
        self.nd[a].next = b;
        self.nd[b].prev = a;
        self.nd[a2].next = an;
        self.nd[an].prev = a2;
        self.nd[b2].next = a2;
        self.nd[a2].prev = b2;
        self.nd[bp].next = b2;
        self.nd[b2].prev = bp;
        b2
    }
    fn linked(&mut self, pts: &[[f64; 2]], cw: bool) -> usize {
        let len = pts.len();
        let mut last = NIL;
        let mut sum = 0.0f64;
        let mut j = if len > 0 { len - 1 } else { 0 };
        for i in 0..len {
            sum += (pts[j][0] - pts[i][0]) * (pts[i][1] + pts[j][1]);
            j = i;
        }
        if cw == (sum > 0.0) {
            for i in 0..len { last = self.ins(self.verts + i, pts[i], last); }
        } else {
            for i in (0..len).rev() { last = self.ins(self.verts + i, pts[i], last); }
        }
        if last != NIL {
            let ln = self.nd[last].next;
            if self.eq(last, ln) { self.rm(last); last = ln; }
        }
        self.verts += len;
        last
    }
    fn leftmost(&self, start: usize) -> usize {
        let mut p = start;
        let mut lm = start;
        loop {
            if self.x(p) < self.x(lm) || (self.x(p) == self.x(lm) && self.y(p) < self.y(lm)) { lm = p; }
            p = self.nx(p);
            if p == start { break; }
        }
        lm
    }
    fn inter_poly(&self, a: usize, b: usize) -> bool {
        let mut p = a;
        loop {
            let n = self.nx(p);
            if self.nd[p].i != self.nd[a].i && self.nd[n].i != self.nd[a].i
                && self.nd[p].i != self.nd[b].i && self.nd[n].i != self.nd[b].i
                && self.inter(p, n, a, b) { return true; }
            p = n;
            if p == a { break; }
        }
        false
    }
    fn valid_diag(&self, a: usize, b: usize) -> bool {
        self.nd[self.nx(a)].i != self.nd[b].i && self.nd[self.pv(a)].i != self.nd[b].i
            && !self.inter_poly(a, b)
            && ((self.loc_in(a, b) && self.loc_in(b, a) && self.mid_in(a, b)
                && (self.area(self.pv(a), a, self.pv(b)) != 0.0 || self.area(a, self.pv(b), b) != 0.0))
                || (self.eq(a, b) && self.area(self.pv(a), a, self.nx(a)) > 0.0
                    && self.area(self.pv(b), b, self.nx(b)) > 0.0))
    }
    fn find_bridge(&self, hole: usize, outer: usize) -> usize {
        let mut p = outer;
        let hx = self.x(hole);
        let hy = self.y(hole);
        let mut qx = f64::NEG_INFINITY;
        let mut m = NIL;
        loop {
            let n = self.nx(p);
            if hy <= self.y(p) && hy >= self.y(n) && self.y(n) != self.y(p) {
                let x = self.x(p) + (hy - self.y(p)) * (self.x(n) - self.x(p)) / (self.y(n) - self.y(p));
                if x <= hx && x > qx {
                    qx = x;
                    m = if self.x(p) < self.x(n) { p } else { n };
                    if x == hx { return m; }
                }
            }
            p = n;
            if p == outer { break; }
        }
        if m == NIL { return NIL; }
        let stop = m;
        let mut tan_min = f64::INFINITY;
        let mx = self.x(m);
        let my = self.y(m);
        p = m;
        loop {
            let px = self.x(p);
            let py = self.y(p);
            if hx >= px && px >= mx && hx != px
                && pit(if hy < my { hx } else { qx }, hy, mx, my, if hy < my { qx } else { hx }, hy, px, py)
            {
                let t = (hy - py).abs() / (hx - px);
                if self.loc_in(p, hole)
                    && (t < tan_min || (t == tan_min && (px > self.x(m) || self.sect(m, p))))
                {
                    m = p;
                    tan_min = t;
                }
            }
            p = self.nx(p);
            if p == stop { break; }
        }
        m
    }
    fn elim_hole(&mut self, hole: usize, outer: usize) -> usize {
        let br = self.find_bridge(hole, outer);
        if br == NIL { return outer; }
        let brr = self.split_poly(br, hole);
        let t = self.nx(brr);
        self.filt(brr, t);
        let t2 = self.nx(br);
        self.filt(br, t2)
    }
    fn elim_holes(&mut self, pts: &[Vec<[f64; 2]>], mut outer: usize) -> usize {
        let mut q: Vec<usize> = vec![];
        for i in 1..pts.len() {
            let l = self.linked(&pts[i], false);
            if l != NIL {
                if self.nx(l) == l { self.nd[l].steiner = true; }
                let lm = self.leftmost(l);
                q.push(lm);
            }
        }
        q.sort_by(|&a, &b| self.x(a).partial_cmp(&self.x(b)).unwrap());
        for h in q { outer = self.elim_hole(h, outer); }
        outer
    }
    fn zord(&self, x_: f64, y_: f64) -> i32 {
        let mut x = ((x_ - self.min_x) * self.inv) as i32;
        let mut y = ((y_ - self.min_y) * self.inv) as i32;
        x = (x | (x << 8)) & 0x00ff00ff;
        x = (x | (x << 4)) & 0x0f0f0f0f;
        x = (x | (x << 2)) & 0x33333333;
        x = (x | (x << 1)) & 0x55555555;
        y = (y | (y << 8)) & 0x00ff00ff;
        y = (y | (y << 4)) & 0x0f0f0f0f;
        y = (y | (y << 2)) & 0x33333333;
        y = (y | (y << 1)) & 0x55555555;
        x | (y << 1)
    }
    fn index_curve(&mut self, start: usize) {
        let mut p = start;
        loop {
            if self.nd[p].z == 0 { self.nd[p].z = self.zord(self.x(p), self.y(p)); }
            self.nd[p].pz = self.nd[p].prev;
            self.nd[p].nz = self.nd[p].next;
            p = self.nd[p].next;
            if p == start { break; }
        }
        let pz = self.nd[p].pz;
        self.nd[pz].nz = NIL;
        self.nd[p].pz = NIL;
        self.sort_linked(p);
    }
    fn sort_linked(&mut self, l0: usize) -> usize {
        let mut list = l0;
        let mut in_size = 1i32;
        loop {
            let mut p = list;
            list = NIL;
            let mut tail = NIL;
            let mut nm = 0;
            while p != NIL {
                nm += 1;
                let mut q = p;
                let mut ps = 0i32;
                for _ in 0..in_size {
                    ps += 1;
                    q = self.nd[q].nz;
                    if q == NIL { break; }
                }
                let mut qs = in_size;
                while ps > 0 || (qs > 0 && q != NIL) {
                    let e;
                    if ps == 0 { e = q; q = self.nd[q].nz; qs -= 1; }
                    else if qs == 0 || q == NIL { e = p; p = self.nd[p].nz; ps -= 1; }
                    else if self.nd[p].z <= self.nd[q].z { e = p; p = self.nd[p].nz; ps -= 1; }
                    else { e = q; q = self.nd[q].nz; qs -= 1; }
                    if tail != NIL { self.nd[tail].nz = e; } else { list = e; }
                    self.nd[e].pz = tail;
                    tail = e;
                }
                p = q;
            }
            self.nd[tail].nz = NIL;
            if nm <= 1 { return list; }
            in_size *= 2;
        }
    }
    fn is_ear(&self, ear: usize) -> bool {
        let a = self.pv(ear);
        let b = ear;
        let c = self.nx(ear);
        if self.area(a, b, c) >= 0.0 { return false; }
        let mut p = self.nx(self.nx(ear));
        while p != self.pv(ear) {
            if pit(self.x(a), self.y(a), self.x(b), self.y(b), self.x(c), self.y(c), self.x(p), self.y(p))
                && self.area(self.pv(p), p, self.nx(p)) >= 0.0 { return false; }
            p = self.nx(p);
        }
        true
    }
    fn is_ear_hashed(&self, ear: usize) -> bool {
        let a = self.pv(ear);
        let b = ear;
        let c = self.nx(ear);
        if self.area(a, b, c) >= 0.0 { return false; }
        let (ax, ay) = (self.x(a), self.y(a));
        let (bx, by) = (self.x(b), self.y(b));
        let (cx, cy) = (self.x(c), self.y(c));
        let mntx = ax.min(bx.min(cx));
        let mnty = ay.min(by.min(cy));
        let mxtx = ax.max(bx.max(cx));
        let mxty = ay.max(by.max(cy));
        let minz = self.zord(mntx, mnty);
        let maxz = self.zord(mxtx, mxty);
        let mut p = self.nd[ear].pz;
        let mut n = self.nd[ear].nz;
        while p != NIL && self.nd[p].z >= minz && n != NIL && self.nd[n].z <= maxz {
            if self.x(p) >= mntx && self.x(p) <= mxtx && self.y(p) >= mnty && self.y(p) <= mxty
                && p != a && p != c
                && pit(ax, ay, bx, by, cx, cy, self.x(p), self.y(p))
                && self.area(self.pv(p), p, self.nx(p)) >= 0.0 { return false; }
            p = self.nd[p].pz;
            if self.x(n) >= mntx && self.x(n) <= mxtx && self.y(n) >= mnty && self.y(n) <= mxty
                && n != a && n != c
                && pit(ax, ay, bx, by, cx, cy, self.x(n), self.y(n))
                && self.area(self.pv(n), n, self.nx(n)) >= 0.0 { return false; }
            n = self.nd[n].nz;
        }
        while p != NIL && self.nd[p].z >= minz {
            if p != self.pv(ear) && p != self.nx(ear)
                && pit(ax, ay, bx, by, cx, cy, self.x(p), self.y(p))
                && self.area(self.pv(p), p, self.nx(p)) >= 0.0 { return false; }
            p = self.nd[p].pz;
        }
        while n != NIL && self.nd[n].z <= maxz {
            if n != self.pv(ear) && n != self.nx(ear)
                && pit(ax, ay, bx, by, cx, cy, self.x(n), self.y(n))
                && self.area(self.pv(n), n, self.nx(n)) >= 0.0 { return false; }
            n = self.nd[n].nz;
        }
        true
    }
    fn cure(&mut self, start0: usize) -> usize {
        let mut start = start0;
        let mut p = start;
        loop {
            let a = self.pv(p);
            let b = self.nx(self.nx(p));
            if !self.eq(a, b) && self.inter(a, p, self.nx(p), b) && self.loc_in(a, b) && self.loc_in(b, a) {
                self.ind.push(self.nd[a].i);
                self.ind.push(self.nd[p].i);
                self.ind.push(self.nd[b].i);
                self.rm(p);
                let pn = self.nd[p].next;
                self.rm(pn);
                p = b;
                start = b;
            }
            p = self.nd[p].next;
            if p == start { break; }
        }
        self.filt(p, NIL)
    }
    fn split_earcut(&mut self, start: usize) {
        let mut a = start;
        loop {
            let mut b = self.nx(self.nx(a));
            while b != self.pv(a) {
                if self.nd[a].i != self.nd[b].i && self.valid_diag(a, b) {
                    let mut c = self.split_poly(a, b);
                    let t = self.nx(a);
                    let a2 = self.filt(a, t);
                    let t2 = self.nx(c);
                    c = self.filt(c, t2);
                    self.ec(a2, 0);
                    self.ec(c, 0);
                    return;
                }
                b = self.nx(b);
            }
            a = self.nx(a);
            if a == start { break; }
        }
    }
    fn ec(&mut self, ear0: usize, pass: i32) {
        if ear0 == NIL { return; }
        let mut ear = ear0;
        if pass == 0 && self.hashing { self.index_curve(ear); }
        let mut stop = ear;
        while self.pv(ear) != self.nx(ear) {
            let prev = self.pv(ear);
            let next = self.nx(ear);
            let ok = if self.hashing { self.is_ear_hashed(ear) } else { self.is_ear(ear) };
            if ok {
                self.ind.push(self.nd[prev].i);
                self.ind.push(self.nd[ear].i);
                self.ind.push(self.nd[next].i);
                self.rm(ear);
                ear = self.nx(next);
                stop = self.nx(next);
                continue;
            }
            ear = next;
            if ear == stop {
                if pass == 0 {
                    let f = self.filt(ear, NIL);
                    self.ec(f, 1);
                } else if pass == 1 {
                    let f = self.filt(ear, NIL);
                    let c = self.cure(f);
                    self.ec(c, 2);
                } else if pass == 2 {
                    self.split_earcut(ear);
                }
                break;
            }
        }
    }
    pub fn run(&mut self, pts: &[Vec<[f64; 2]>]) {
        self.ind.clear();
        self.verts = 0;
        if pts.is_empty() { return; }
        let mut th: i32 = 80;
        let mut i = 0;
        while th >= 0 && i < pts.len() { th -= pts[i].len() as i32; i += 1; }
        let mut outer = self.linked(&pts[0], true);
        if outer == NIL || self.pv(outer) == self.nx(outer) { return; }
        if pts.len() > 1 { outer = self.elim_holes(pts, outer); }
        self.hashing = th < 0;
        if self.hashing {
            let mut p = self.nx(outer);
            self.min_x = self.x(outer); self.max_x = self.min_x;
            self.min_y = self.y(outer); self.max_y = self.min_y;
            loop {
                let (x, y) = (self.x(p), self.y(p));
                self.min_x = self.min_x.min(x);
                self.min_y = self.min_y.min(y);
                self.max_x = self.max_x.max(x);
                self.max_y = self.max_y.max(y);
                p = self.nx(p);
                if p == outer { break; }
            }
            let s = (self.max_x - self.min_x).max(self.max_y - self.min_y);
            self.inv = if s != 0.0 { 32767.0 / s } else { 0.0 };
        }
        self.ec(outer, 0);
        self.nd.clear();
    }
}

pub fn ref_earcut(poly: &[Vec<[f64; 2]>]) -> Vec<u32> {
    let mut r = R::new();
    r.run(poly);
    r.ind
}
